    try {
        scwin.delSpecialChar(txb_pSTD_CD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS15500.txb_pSTD_CD_onkeyup" });
    }
};

/**
 * @method
 * @name img_pISUR_CD_onclick
 * @description 발행기관 코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_pISUR_CD_onclick = async function () {
    try {
        await scwin.openInsPopup(txb_pISUR_CD, "", "ULDINS90400", "발행기관 코드", "550", "450");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15500.img_pISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 수정
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function (e) {
    try {
        if (await scwin.modify("N") === false) return;
        txb_DEL_RSN.setValue("");
        await scwin.openInsPopup(txb_DEL_RSN, "", "ULDINS93900", "수정사유", "470", "340");
        // 수정사유가 입력되면 저장 처리(AS-IS 는 팝업이 opener 의 ins_modify 를 직접 호출)
        if (!$c.util.isEmpty(txb_DEL_RSN.getValue())) await scwin.modify("Y");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15500.btn_modify_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 삭제
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function (e) {
    try {
        txb_param1.setValue("");
        txb_param2.setValue("");
        scwin.getParam();

        // 삭제 신청건수 확인후
        const delcnt = dma_bcMgtDetail.get("delcnt");
        if (delcnt > 0) {
            // 삭제 메시지 확인 ... 확인되면 -> 삭제승인 화면이동 ,null,null, 아니면 바로 삭제
            await scwin.alertRequiredDelByWeb();
        } else {
            // 관리 삭제로직
            // 삭제팝업호출
            // 삭제사유 전달받을 input박스 정의한다.
            if (!(await $c.win.confirm("삭제하시겠습니까?"))) return; // AS-IS $c.cm.alertDelConfirm(미반입) 대체
            txb_DEL_RSN.setValue("");
            await scwin.openInsPopup(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "350");
            // 삭제사유가 입력되면 삭제 처리(AS-IS 는 팝업이 opener 의 ins_remove 를 직접 호출)
            if (!$c.util.isEmpty(txb_DEL_RSN.getValue())) await scwin.remove();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15500.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_file_onclick
 * @description 첨부파일확인
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_file_onclick = async function(e) {
    try {
        /*
        txb_param1 에는 신청ID
        txb_param2 에는 구분값을 넣는데..
        + "1 : 발행기관신청, 팩스-발행기관신청 \n"
        + "2 : 표준코드신청, 팩스-표준코드신청 \n"
        + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
         */

        txb_param1.setValue(dma_bcMgtDetail.get("stdCdApplId")); // 표준코드 신청 ID
        txb_param2.setValue("2");
        scwin.getParam();

        await scwin.openInsPopup("", "", "ULDINS91100", "첨부파일", "655", "350");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15500.btn_file_onclick" });
    }
};

