/**
 * @method
 * @name grd_bcMgtList_oncellclick
 * @description grd_bcMgtList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_bcMgtList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const bcMgtListdata = dlt_bcMgtList.getRowJSON(rowIndex);
        const stdCd = bcMgtListdata.stdCd;

        await scwin.searchDetail(stdCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15500.grd_bcMgtList_oncellclick" });
    }
};

/**
 * @method
 * @name img_COM_NM_INFO_onclick
