        scwin.getParam();

        await scwin.openInsPopup("", "", "ULDINS91600", "발행기관 상세정보", "740", "835");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15500.img_COM_NM_INFO_onclick" });
    }
};

/**
 * @method
 * @name cmb_cb_p_group_onchange
 * @description CFI 그룹
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onchange = function (info) {
    try {
        if (cmb_cb_p_group.getValue() !== "") {
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03", "C", cmb_cb_p_group.getValue(), "1", "");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr2, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03", "C", cmb_cb_p_group.getValue(), "2", "");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr3, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03", "C", cmb_cb_p_group.getValue(), "3", "");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): $c.cm.insCfiSet(dts_cfi_attr4, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03", "C", cmb_cb_p_group.getValue(), "4", "");
            // await $c.win.alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): label_attr1.setValue("(" + dts_cfi_attr1.NameValue(2, "HEAD_NM") + ")");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): label_attr2.setValue("(" + dts_cfi_attr2.NameValue(2, "HEAD_NM") + ")");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): label_attr3.setValue("(" + dts_cfi_attr3.NameValue(2, "HEAD_NM") + ")");
            // TODO Stage2(CFI 코드 조회 API 미구현 — Gauce 데이터셋): label_attr4.setValue("(" + dts_cfi_attr4.NameValue(2, "HEAD_NM") + ")");
        }
        scwin.changeCfi();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS15500.cmb_cb_p_group_onchange" });
    }
};

