///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setComboCode
 * @description 공통코드 조회 — 공통코드 API(commCodeValue-select)로 selectbox 데이터 설정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setComboCode = async function (){
    /**
     * CURR_TP_CD               발행통화(0:기타.1:원화,2:달러,3:엔화,...9:싱가폴달러)
     * DOM_FORN_STKCERT_TP_CD   국내/해외주권 발행구분(D:국내,I:해외)
     * LIST_STAT_CD             상장여부(D:상장폐지,I:미발행,N:비상장,Y:상장,Z:기타)
     * STD_CD_APCT_TP_CD        신청인 구분(1:발행기관,2:대표주관회사,3:채권부,4:기타,5:온라인소액투자중개업자)
     */

    dma_searchCode.set("codeList", "DOM_FORN_STKCERT_TP_CD,CURR_TP_CD,LIST_STAT_CD,STD_CD_APCT_TP_CD");

    const sbmOptions = {
        id : "sbm_searchCode",
        action : "/api/isin/common/api/commCode/commCodeValue-select",
        method : "get",
        ref : "dma_searchCode",
        target : "dlt_DOM_FORN_STKCERT_TP_CD=body.DOM_FORN_STKCERT_TP_CD,dlt_CURR_TP_CD=body.CURR_TP_CD,dlt_LIST_STAT_CD=body.LIST_STAT_CD,dlt_STD_CD_APCT_TP_CD=body.STD_CD_APCT_TP_CD",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name search
 * @description 수익증권 표준코드관리  목록 조회한다.
 * @returns {Promise<Boolean>}
 * @hidden N
 */
scwin.search = async function() {
    if ($c.util.isEmpty(txb_pSTD_CD.getValue()) &&
        $c.util.isEmpty(txb_pISU_NM.getValue()) &&
        $c.util.isEmpty(txb_pISUR_CD.getValue()) &&
        $c.util.isEmpty(edt_pSTD_CD_GRNT_DD_SDATE.getValue()) &&
        $c.util.isEmpty(edt_pSTD_CD_GRNT_DD_EDATE.getValue())) {
        await $c.win.alert("조회 파라메터가 부족합니다");
        return;
    }

    // 검색일 체크
    if (!(await scwin.checkFromTo(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE, "발행일"))) return false;
    if (!(await scwin.checkFromTo(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE, "코드부여일"))) return false;

    // 데이터 초기화
    dma_bcMgtDetail.reset();

    dma_search.set("stdCd", txb_pSTD_CD.getValue());
    dma_search.set("isuNm", txb_pISU_NM.getValue());
    dma_search.set("isurCd", txb_pISUR_CD.getValue());
    dma_search.set("isuDdSdate", edt_pISU_DD_SDATE.getValue());
    dma_search.set("isuDdEdate", edt_pISU_DD_EDATE.getValue());
    dma_search.set("stdCdGrntDdSdate", edt_pSTD_CD_GRNT_DD_SDATE.getValue());
    dma_search.set("stdCdGrntDdEdate", edt_pSTD_CD_GRNT_DD_EDATE.getValue());

    const sbmOptions = {
        id : "sbm_search",
        action : "/api/isin/api/stdcdMgtGrp/bcMgt/bcMgtList-select",
        method : "get",
        ref : "dma_search",
        target : "dlt_bcMgtList=body",
        gridview : "grd_bcMgtList|focus"
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    if (sbmRtn && sbmRtn.skipped) return;
    await scwin.sbm_search_submitdone(sbmRtn);
};

/**
 * @method
 * @name searchDetail
 * @description 수익증권 표준코드관리 상세 조회한다.
 * @param {String} STD_CD 표준코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function(STD_CD) {
    // 데이터 초기화
    dma_bcMgtDetail.reset();

    // 수익증권 표준코드관리
    dma_search2.set("stdCd", STD_CD);

    const sbmOptions = {
        id : "sbm_searchDtl",
        action : "/api/isin/api/stdcdMgtGrp/bcMgt/bcMgtDetail-select",
        method : "get",
        ref : "dma_search2",
        target : "dma_bcMgtDetail=body",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    if (sbmRtn && sbmRtn.skipped) return;
    await scwin.sbm_searchDtl_submitdone(sbmRtn);
};

/**
 * @method
 * @name modify
 * @description 수익증권 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 * @param {String} mflag 검증만 수행 여부(N: 검증만, Y: 저장)
 * @returns {Promise<Boolean>}
 * @hidden N
 */
scwin.modify = async function(mflag) {
    if (!$c.data.isModified(dma_bcMgtDetail)) {
        await $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }
    // 필수 입력 검증(규칙 24 — validateDataCollect)
    const isValid = await $c.validate.validateDataCollect(panel_1, {
        fields : {
            txb_STD_CD : { required : true, name : "표준코드" },
            txb_ISU_NM : { required : true, name : "한글종목명" },
            txb_ISU_ABBRV : { required : true, name : "한글종목약명" },
            txb_ISU_ENG_NM : { required : true, name : "영문종목명" },
            txb_ISU_ENG_ABBRV : { required : true, name : "영문종목약명" }
        }
    });
    if (!isValid) return false;
    // byte 길이 검사(AS-IS 규약: 한글 2byte — $c.fil.checkMaxLength 가 초과 시 알림·포커스)
    if (!$c.fil.checkMaxLength(txb_STD_CD, 12, "표준코드")) return false;
    if (!$c.fil.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) return false;
    if (!$c.fil.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) return false;
    if (!$c.fil.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) return false;
    if (!$c.fil.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) return false;
    if (!$c.fil.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) return false;

    /*
    //CFI체크
    if (cmb_cb_p_group.getValue() == "") {
        await $c.win.alert("[CFI_그룹] 을(를) 입력하셔야 합니다.");
        cmb_cb_p_group.focus();
        return false;
    }
    if (cmb_cb_p_attr_1.getValue() == "") {
        await $c.win.alert("[CFI_1차속성] 을(를) 입력하셔야 합니다.");
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if (cmb_cb_p_attr_2.getValue() == "") {
        await $c.win.alert("[CFI_2차속성] 을(를) 입력하셔야 합니다.");
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if (cmb_cb_p_attr_3.getValue() == "") {
        await $c.win.alert("[CFI_3차속성] 을(를) 입력하셔야 합니다.");
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if (cmb_cb_p_attr_4.getValue() == "") {
        await $c.win.alert("[CFI_4차속성] 을(를) 입력하셔야 합니다.");
        cmb_cb_p_attr_4.focus();
        return false;
    }
     */

    if (mflag === "N") return;

    dma_proc.setJSON(dma_bcMgtDetail.getJSON());
    dma_proc.set("transtrEmpNo", scwin.empNo);
    dma_proc.set("empNm", scwin.empNm);

    const sbmOptions = {
        id : "sbm_save",
        action : "/api/isin/api/stdcdMgtGrp/bcMgt/bcMgt-save",
        method : "post",
        ref : "dma_proc",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    if (sbmRtn && sbmRtn.skipped) return;
    await scwin.sbm_save_submitdone(sbmRtn);
};

/**
 * @method
 * @name remove
 * @description 표준코드 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.remove = async function() {
    dma_delete.set("transtrEmpNo", scwin.empNo);
    dma_delete.set("empNm", scwin.empNm);
    dma_delete.set("stdCd", txb_STD_CD.getValue());
    dma_delete.set("isuNm", txb_ISU_NM.getValue());
    dma_delete.set("chgRsn", txb_DEL_RSN.getValue());

    const sbmOptions = {
        id : "sbm_delete",
        action : "/api/isin/api/stdcdMgtGrp/bcMgt/bcMgt-delete",
        method : "post",
        ref : "dma_delete",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    if (sbmRtn && sbmRtn.skipped) return;
    await scwin.sbm_delete_submitdone(sbmRtn);
};

